'use client'

import { useTaskManager } from '@/hooks/useTaskManager'
import { TaskCard } from '@/components/TaskCard'
import { TaskForm } from '@/components/TaskForm'
import { Task } from '@/types/task'
import { ListTodo, Clock, CheckCircle2 } from 'lucide-react'

export function TaskDashboard() {
  const { tasks, isLoading, addTask, updateTask, deleteTask, getTasksByStatus } = useTaskManager()

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-white/60">Loading tasks...</div>
      </div>
    )
  }

  const todoTasks = getTasksByStatus('todo')
  const inProgressTasks = getTasksByStatus('in-progress')
  const completedTasks = getTasksByStatus('completed')

  const stats = [
    {
      label: 'To Do',
      count: todoTasks.length,
      icon: ListTodo,
      color: 'text-gray-400',
    },
    {
      label: 'In Progress',
      count: inProgressTasks.length,
      icon: Clock,
      color: 'text-purple-400',
    },
    {
      label: 'Completed',
      count: completedTasks.length,
      icon: CheckCircle2,
      color: 'text-green-400',
    },
  ]

  return (
    <div className="space-y-8">
      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {stats.map((stat) => {
          const Icon = stat.icon
          return (
            <div
              key={stat.label}
              className="bg-black/40 border border-white/10 rounded-lg p-6 hover:border-white/20 transition-colors"
            >
              <div className="flex items-center gap-3">
                <Icon className={`${stat.color}`} size={24} />
                <div>
                  <p className="text-white/60 text-sm">{stat.label}</p>
                  <p className="text-white text-2xl font-bold">{stat.count}</p>
                </div>
              </div>
            </div>
          )
        })}
      </div>

      {/* Add Task Form */}
      <TaskForm onAdd={addTask} />

      {/* Task Lists by Status */}
      <div className="space-y-8">
        {/* To Do */}
        {todoTasks.length > 0 && (
          <div>
            <h2 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
              <ListTodo size={24} className="text-gray-400" />
              To Do ({todoTasks.length})
            </h2>
            <div className="grid gap-4">
              {todoTasks.map((task) => (
                <TaskCard
                  key={task.id}
                  task={task}
                  onUpdate={updateTask}
                  onDelete={deleteTask}
                />
              ))}
            </div>
          </div>
        )}

        {/* In Progress */}
        {inProgressTasks.length > 0 && (
          <div>
            <h2 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
              <Clock size={24} className="text-purple-400" />
              In Progress ({inProgressTasks.length})
            </h2>
            <div className="grid gap-4">
              {inProgressTasks.map((task) => (
                <TaskCard
                  key={task.id}
                  task={task}
                  onUpdate={updateTask}
                  onDelete={deleteTask}
                />
              ))}
            </div>
          </div>
        )}

        {/* Completed */}
        {completedTasks.length > 0 && (
          <div>
            <h2 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
              <CheckCircle2 size={24} className="text-green-400" />
              Completed ({completedTasks.length})
            </h2>
            <div className="grid gap-4">
              {completedTasks.map((task) => (
                <TaskCard
                  key={task.id}
                  task={task}
                  onUpdate={updateTask}
                  onDelete={deleteTask}
                />
              ))}
            </div>
          </div>
        )}

        {/* Empty State */}
        {tasks.length === 0 && (
          <div className="text-center py-16">
            <ListTodo size={64} className="text-white/20 mx-auto mb-4" />
            <h3 className="text-xl font-semibold text-white mb-2">No tasks yet</h3>
            <p className="text-white/60">Create your first task to get started!</p>
          </div>
        )}
      </div>
    </div>
  )
}

