'use client'

import { Task } from '@/types/task'
import { Trash2, Edit2, Check } from 'lucide-react'
import { useState } from 'react'

interface TaskCardProps {
  task: Task
  onUpdate: (id: string, updates: Partial<Task>) => void
  onDelete: (id: string) => void
}

export function TaskCard({ task, onUpdate, onDelete }: TaskCardProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [editTitle, setEditTitle] = useState(task.title)
  const [editDescription, setEditDescription] = useState(task.description || '')

  const priorityColors = {
    low: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    medium: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    high: 'bg-red-500/20 text-red-400 border-red-500/30',
  }

  const statusColors = {
    'todo': 'bg-gray-500/20 text-gray-400 border-gray-500/30',
    'in-progress': 'bg-purple-500/20 text-purple-400 border-purple-500/30',
    'completed': 'bg-green-500/20 text-green-400 border-green-500/30',
  }

  const handleSave = () => {
    onUpdate(task.id, {
      title: editTitle,
      description: editDescription,
    })
    setIsEditing(false)
  }

  const cycleStatus = () => {
    const statuses: Task['status'][] = ['todo', 'in-progress', 'completed']
    const currentIndex = statuses.indexOf(task.status)
    const nextStatus = statuses[(currentIndex + 1) % statuses.length]
    onUpdate(task.id, { status: nextStatus })
  }

  return (
    <div className="group relative bg-black/40 border border-white/10 rounded-lg p-4 hover:border-white/20 transition-all">
      <div className="flex items-start justify-between gap-3 mb-3">
        <div className="flex-1">
          {isEditing ? (
            <input
              type="text"
              value={editTitle}
              onChange={(e) => setEditTitle(e.target.value)}
              className="w-full bg-white/5 border border-white/10 rounded px-2 py-1 text-white outline-none focus:border-white/30"
              autoFocus
            />
          ) : (
            <h3 className="font-semibold text-white text-lg">{task.title}</h3>
          )}
        </div>
        <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
          {isEditing ? (
            <button
              onClick={handleSave}
              className="p-1.5 rounded hover:bg-green-500/20 text-green-400 transition-colors"
            >
              <Check size={18} />
            </button>
          ) : (
            <button
              onClick={() => setIsEditing(true)}
              className="p-1.5 rounded hover:bg-white/10 text-white/60 hover:text-white transition-colors"
            >
              <Edit2 size={18} />
            </button>
          )}
          <button
            onClick={() => onDelete(task.id)}
            className="p-1.5 rounded hover:bg-red-500/20 text-red-400 transition-colors"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      {isEditing ? (
        <textarea
          value={editDescription}
          onChange={(e) => setEditDescription(e.target.value)}
          className="w-full bg-white/5 border border-white/10 rounded px-2 py-1 text-white/80 text-sm outline-none focus:border-white/30 mb-3 min-h-[60px]"
          placeholder="Description..."
        />
      ) : task.description ? (
        <p className="text-white/60 text-sm mb-3">{task.description}</p>
      ) : null}

      <div className="flex items-center gap-2 flex-wrap">
        <button
          onClick={cycleStatus}
          className={`px-3 py-1 rounded-full text-xs font-medium border ${statusColors[task.status]} cursor-pointer hover:opacity-80 transition-opacity`}
        >
          {task.status}
        </button>
        <span className={`px-3 py-1 rounded-full text-xs font-medium border ${priorityColors[task.priority]}`}>
          {task.priority}
        </span>
        <span className="text-xs text-white/40 ml-auto">
          {new Date(task.updatedAt).toLocaleDateString()}
        </span>
      </div>
    </div>
  )
}

